//  - Keep the logical loop order i -> j -> k identical to the Polybench
//    reference to preserve the accumulation order across C elements.
//  - Eliminate the inner `if (k < i)` branch by restricting the traverser
//    over 'k' using `noarr::slice<'k'>(0, i)`; this keeps exactly the same
//    (k) values but avoids evaluating the branch for k >= i.
//  - Hoist the frequently used B[i][j] out of the k-loop, so it is loaded
//    once per (i,j) instead of once per k-iteration.
//  - Keep all iteration expressed in terms of Noarr traversers and states.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k (symmetric, lower stored)
	// B: i x j
	#pragma scop
	// Outer loop over i – we keep this as the outermost loop to match the
	// original Polybench symm kernel's dependence structure.
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// Loop over j
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			const std::size_t j_idx = get_index<'j'>(state_ij);

			// State for (i,j), used several times
			auto s_ij = state_ij;

			// B[i][j] is reused in the inner k-loop, so load it once
			const num_t Bij = B[s_ij];

			// Accumulator corresponding to the "temp2" variable in the
			// Polybench reference implementation.
			num_t temp2 = 0;

			// Inner loop over k, but only for k < i.
			// Instead of iterating over the full 'k' range and branching
			// on (k < i), we restrict the traverser to [0, i_idx) in 'k'.
			// This preserves the exact sequence of (k) values that execute
			// the body, while avoiding the branch.
			auto trav_ij_k = trav_ij.order(noarr::slice<'k'>(0, i_idx));
			trav_ij_k.for_each([&](auto state_ijk) {
				const std::size_t k_idx = get_index<'k'>(state_ijk);

				// States for the required accesses:
				//  - C[k][j] and B[k][j]
				//  - A[i][k]
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				auto s_ik = idx<'i', 'k'>(i_idx, k_idx);

				const num_t Aik = A[s_ik];

				C[s_kj] += alpha * Bij * Aik;
				temp2   +=          B[s_kj] * Aik;
			});

			// Diagonal element A[i][i]
			const num_t Aii = A[idx<'i', 'k'>(i_idx, i_idx)];

			// Final update of C[i][j]
			C[s_ij] = beta * C[s_ij]
			        + alpha * Bij * Aii
			        + alpha * temp2;
		});
	});
	#pragma endscop
