constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Tunable blocking size for the j-dimension (columns).
	// This constant only affects the traversal order, not the result.
	static constexpr std::size_t j_block_size = 64;

	// C: i x j
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (M x M)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j  (M x N)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);

	// Proto-structure used to tile the 'j' dimension in all hot traversals.
	// We use the dynamic variant so that N need not be a multiple of j_block_size.
	DEFINE_PROTO_STRUCT(
		j_blocking,
		noarr::into_blocks_dynamic<'j', 'J', 'j', 'p'>(noarr::lit<j_block_size>));
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
//
// Original mathematical operation (left-side symmetric matrix-matrix multiply):
//   C_out = beta * C_in + alpha * A * B
// where
//   - A is M x M symmetric, lower triangle stored
//   - B is M x N
//   - C is M x N
//
// This implementation uses two phases:
//   1) Scale C by beta and add the diagonal contribution alpha * A[i][i] * B[i][j].
//   2) For each off-diagonal pair (i,k) with k < i, update rows k and i in C
//      using A[i][k] and rows i,k of B.
//
// Compared to the original k-inner algorithm with a scalar reduction temp2,
// this version:
//   - keeps j as the innermost loop, so we stream over rows C[*][j], B[*][j]
//   - removes the inner k-condition and temp2 reduction
//   - still performs exactly the same floating-point operations (up to reordering).
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	#pragma scop

	// -------------------------------------------------------------------
	// Phase 1: scale C by beta and add the diagonal term
	//          alpha * A[i][i] * B[i][j]  for all i,j.
	//
	// We traverse row-by-row (i outer, j inner) and tile the j dimension
	// with tuning.j_blocking to improve cache and vectorization behavior.
	// -------------------------------------------------------------------
	traverser(C, B)
		.order(tuning.j_blocking)
		.template for_dims<'i'>([=](auto trav_i) {
			// i is fixed in trav_i
			auto state_i = trav_i.state();
			auto i_idx   = get_index<'i'>(state_i);

			// Diagonal element A[i][i] is reused for all j in this row.
			// Note: A has layout i x k, with k as the inner dimension.
			num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];

			// Iterate all j (internally blocked by tuning.j_blocking).
			// The state contains only original dimensions ('i','j') even
			// though the traverser internally uses the blocked view.
			trav_i.for_each([&](auto state_ij) {
				C[state_ij] = beta * C[state_ij] + alpha * B[state_ij] * a_ii;
			});
		});

	// -------------------------------------------------------------------
	// Phase 2: off-diagonal part. For each pair (i,k) with k < i we update
	//   C[k][j] and C[i][j] for all j:
	//
	//   C[k][j] += alpha * B[i][j] * A[i][k];
	//   C[i][j] += alpha * B[k][j] * A[i][k];
	//
	// This exactly matches the contribution of the symmetric entry A[i][k]
	// to rows k and i of C in the product A * B.
	//
	// The innermost loop is over j, so we stream over two rows at a time:
	//   - C[k][*], C[i][*]
	//   - B[k][*], B[i][*]
	// giving good spatial locality and an easy-to-vectorize kernel.
	// -------------------------------------------------------------------
	traverser(C, A, B)
		.order(tuning.j_blocking)
		.template for_dims<'i'>([=](auto trav_i) {
			auto state_i = trav_i.state();
			auto i_idx   = get_index<'i'>(state_i);

			// Loop over k; only the strictly lower part k < i participates.
			// The k < i condition is outside the innermost j-loop to avoid
			// per-element branching.
			trav_i.template for_dims<'k'>([=](auto trav_ik) {
				auto state_ik = trav_ik.state();
				auto k_idx    = get_index<'k'>(state_ik);

				if (k_idx < i_idx) {
					// Single A coefficient reused over the whole j-row.
					// A[state_ik] is A[i][k].
					num_t a_ik = A[state_ik];

					// Traverse all j for this (i,k) pair.
					// The state again only exposes original dimensions.
					trav_ik.for_each([&](auto state_ikj) {
						auto j_idx = get_index<'j'>(state_ikj);

						// Build states for the participating matrix elements:
						//   C[k][j], C[i][j], B[i][j], B[k][j]
						auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
						auto s_ij = idx<'i', 'j'>(i_idx, j_idx);

						// C[k][j] += alpha * B[i][j] * A[i][k];
						C[s_kj] += alpha * B[s_ij] * a_ik;

						// C[i][j] += alpha * B[k][j] * A[i][k];
						C[s_ij] += alpha * B[s_kj] * a_ik;
					});
				}
			});
		});

	#pragma endscop
}

} // namespace

