// computation kernel
//
// Original mathematical operation:
//   C := alpha * A * B + beta * C
// with A symmetric, only the lower triangle stored.
// The original code followed a canonical BLAS-like SYMM variant:
//
//   for i
//     for j
//       temp2 = 0
//       for k < i:
//         C[k,j] += alpha * B[i,j] * A[i,k]
//         temp2  +=         B[k,j] * A[i,k]
//       C[i,j] = beta*C[i,j] + alpha*B[i,j]*A[i,i] + alpha*temp2
//
// This is correct but has poor locality for C[k,j] and B[k,j] because
// k is the innermost loop while j is the inner (contiguous) dimension
// in memory.
//
// We reformulate the same computation to improve data locality:
//
// 1. Scale C by beta once:  C[i,j] <- beta * C[i,j]
// 2. Off-diagonal contributions (A(i,k), k < i):
//      for i
//        for k < i
//          temp1 = alpha * A[i,k]
//          for j
//            C[k,j] += temp1 * B[i,j]
//            C[i,j] += temp1 * B[k,j]
// 3. Diagonal contributions (A(i,i)):
//      for i
//        temp1 = alpha * A[i,i]
//        for j
//          C[i,j] += temp1 * B[i,j]
//
// This is algebraically equivalent to the original kernel, but now the
// innermost loop runs over j, giving contiguous accesses in B and C for
// both rows i and k. That greatly improves cache behaviour and enables
// better vectorization.
//
// All loops are expressed in terms of Noarr traversers, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	#pragma scop

	// -----------------------------------------------------------------
	// 1) Pre-scale C: C[i,j] = beta * C[i,j]
	// -----------------------------------------------------------------
	traverser(C).for_each([&](auto state) {
		C[state] *= beta;
	});

	// -----------------------------------------------------------------
	// 2) Symmetric matrix-matrix product C += alpha * A * B
	//    A is symmetric, stored in its lower triangle.
	//
	//    We iterate over i (row of A and C) first. For each i we:
	//      a) handle off-diagonal elements A(i,k) with k < i
	//         (updating rows i and k of C)
	//      b) handle the diagonal A(i,i)
	// -----------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; 'j' and 'k' remain (union over C, A, B)
		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// -------------------------------------------------------------
		// 2a) Off-diagonal part: A(i,k) for k < i
		//     For each pair (i,k) with k < i, we traverse all j and:
		//       C[k,j] += alpha*A[i,k] * B[i,j]
		//       C[i,j] += alpha*A[i,k] * B[k,j]
		// -------------------------------------------------------------
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed; 'j' remains
			auto state_ik = trav_ik.state();
			const std::size_t k_idx = get_index<'k'>(state_ik);

			// Only use the strictly lower triangular part (k < i)
			if (k_idx >= i_idx)
				return;

			// A(i,k) is stored in the lower triangle (k <= i)
			const num_t a_ik = A[state_ik];
			const num_t coeff = alpha * a_ik;

			// Inner-most loop over j for good locality:
			// both C[i, j] / C[k, j] and B[i, j] / B[k, j] are contiguous.
			trav_ik.for_each([&](auto state_ikj) {
				const std::size_t j_idx = get_index<'j'>(state_ikj);

				// States for C(k,j), C(i,j), B(i,j), B(k,j)
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				auto s_ij = idx<'i', 'j'>(i_idx, j_idx);

				C[s_kj] += coeff * B[s_ij]; // C[k,j] += alpha*A[i,k]*B[i,j]
				C[s_ij] += coeff * B[s_kj]; // C[i,j] += alpha*A[i,k]*B[k,j]
			});
		});

		// -------------------------------------------------------------
		// 2b) Diagonal part: A(i,i)
		//     For each i, traverse all j and:
		//       C[i,j] += alpha*A[i,i] * B[i,j]
		//     (C already contains beta*C from the pre-scaling step)
		// -------------------------------------------------------------
		const num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];
		const num_t coeff_diag = alpha * a_ii;

		// We want exactly one iteration per (i,j) pair here.
		// for_dims<'j'> gives us a traverser with i and j fixed.
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			const std::size_t j_idx = get_index<'j'>(state_ij);

			auto s_ij = idx<'i', 'j'>(i_idx, j_idx);

			C[s_ij] += coeff_diag * B[s_ij];
		});
	});

	#pragma endscop
