namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Layouts are chosen to match the access patterns of the kernel:
	//   - C and B: contiguous in 'i' for a fixed 'j'  -> we update C[k][j] and
	//     read B[k][j] with k varying fastest.
	//   - A:       contiguous in 'k' for a fixed 'i'  -> inner loop streams
	//     over k for a fixed row i.
	//
	// This improves spatial locality compared to the original j-major layout.
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec); // C: i x j
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // A: i x k  (M x M)
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec); // B: i x j  (M x N)
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k (symmetric, lower stored)
	// B: i x j
	//
	// Mathematical kernel (PolyBench SYMM, lower storage):
	//
	//   for i in [0, M)
	//     for j in [0, N)
	//       temp2 = 0
	//       for k in [0, i)
	//         C[k][j] += alpha * B[i][j] * A[i][k];
	//         temp2   +=          B[k][j] * A[i][k];
	//       C[i][j] = beta * C[i][j]
	//                + alpha * B[i][j] * A[i][i]
	//                + alpha * temp2;
	//
	// Optimizations (while preserving the above computation):
	//   - Use Noarr traversers exclusively for loop nests.
	//   - Iterate j outermost, then i, to match the i-contiguous layout of
	//     C and B (i is innermost dimension in memory).
	//   - Replace the full k-loop + "if (k < i)" guard by a sliced
	//     traverser over k in [0, i), eliminating useless iterations and
	//     the inner conditional.
	//   - Hoist B[i][j] and A[i][i] out of the inner k-loop.

	#pragma scop
	traverser(C, A, B).template for_dims<'j'>([&](auto trav_j) {
		// Outer loop over the column index j
		trav_j.template for_dims<'i'>([&](auto trav_ij) {
			// Inner loop over the row index i for the current column j

			// State with fixed (i,j). This does not contain 'k'.
			auto state_ij = trav_ij.state();
			auto i_idx = get_index<'i'>(state_ij);
			auto j_idx = get_index<'j'>(state_ij);

			// B[i][j] is invariant across the k-loop; load it once.
			const num_t Bij = B[state_ij];

			num_t temp2 = 0;

			// Restrict k to [0, i_idx). This replaces the original
			//   for all k: if (k < i) { ... }
			// by an explicit range in k, reducing work and branch pressure
			// while keeping the k-iteration order (0,1,...,i-1) unchanged.
			auto trav_k = trav_ij.order(slice<'k'>(0, i_idx));

			trav_k.for_each([&](auto state_ijk) {
				// state_ijk now contains (i,j,k)
				auto k_idx = get_index<'k'>(state_ijk);

				// States for the required accesses:
				//   C[k][j], B[k][j], A[i][k]
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				auto s_ik = idx<'i', 'k'>(i_idx, k_idx);

				const num_t Aik = A[s_ik];

				C[s_kj] += alpha * Bij * Aik;
				temp2   +=          B[s_kj] * Aik;
			});

			// Final update of C[i][j]: use the diagonal element A[i][i]
			// and the accumulated temp2.
			auto s_ii = idx<'i', 'k'>(i_idx, i_idx);
			const num_t Aii = A[s_ii];

			auto &Cij = C[state_ij];

			Cij = beta * Cij
				+ alpha * Bij * Aii
				+ alpha * temp2;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
