// computation kernel
//
// Optimizations vs. original:
// - 2D blocking in the i and j dimensions using Noarr `slice` applied
//   via traverser::order() to improve cache locality for C and B.
//   The block sizes are controlled by I_BLOCK and J_BLOCK above.
//   This adds artificial outer loops over tiles but preserves the
//   mathematical computation (only the iteration order changes).
// - Hoisting A[i][i] out of the j-loop (it depends only on i).
// - Hoisting B[i][j] out of the k-loop (it is reused for all k<i for
//   a given (i,j)).
// - Hoisting index extraction for i outside the j-loop.
// The actual element-wise work is still expressed purely through
// Noarr traversers and index states.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Logical dimensions
	const std::size_t m = C | get_length<'i'>();
	const std::size_t n = C | get_length<'j'>();

	// Base traverser over all three bags; all further traversal
	// shaping is done via .order(...) with proto-structures.
	auto full_trav = noarr::traverser(C, A, B);

	#pragma scop
	// Outer tiling over the i and j dimensions.
	// We keep all inner work expressed with Noarr traversers; the
	// explicit for-loops here are over tile coordinates, not over
	// individual elements.
	for (std::size_t i0 = 0; i0 < m; i0 += I_BLOCK) {
		const std::size_t i_block_len =
			(i0 + I_BLOCK <= m) ? I_BLOCK : (m - i0);

		// Restrict traverser to the current block of i's.
		auto trav_i_block =
			full_trav.order(noarr::slice<'i'>(i0, i_block_len));

		for (std::size_t j0 = 0; j0 < n; j0 += J_BLOCK) {
			const std::size_t j_block_len =
				(j0 + J_BLOCK <= n) ? J_BLOCK : (n - j0);

			// Further restrict to the current block of j's.
			auto trav_block = trav_i_block.order(
				noarr::slice<'j'>(j0, j_block_len));

			// Now traverse the actual data dimensions with Noarr.

			// Loop over i within the current i-tile.
			trav_block.template for_dims<'i'>([=](auto trav_i) {
				// trav_i has 'i' fixed in trav_i.state()
				auto state_i = trav_i.state();
				const std::size_t i_idx = get_index<'i'>(state_i);

				// A[i][i] is reused for all j at this i.
				const num_t Aii = A[noarr::idx<'i', 'k'>(i_idx, i_idx)];

				// Loop over j within the current j-tile.
				trav_i.template for_dims<'j'>([=](auto trav_ij) {
					num_t temp2 = 0;

					auto state_ij = trav_ij.state();
					const std::size_t j_idx = get_index<'j'>(state_ij);

					// Common state for C[i][j] and B[i][j]
					const auto s_ij = state_ij;
					const num_t Bij = B[s_ij];

					// Inner loop over k: we only use k<i, but we keep
					// the full Noarr traversal and guard with a
					// condition to match the original SYMM kernel.
					trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
						auto state_ijk = trav_ijk.state();
						const std::size_t k_idx =
							get_index<'k'>(state_ijk);

						if (k_idx < i_idx) {
							// States for required accesses:
							// C[k][j], B[i][j], B[k][j], A[i][k]
							const auto s_kj =
								noarr::idx<'i', 'j'>(k_idx, j_idx);
							const auto s_ik =
								noarr::idx<'i', 'k'>(i_idx, k_idx);

